entries[158291] = { ["name"] = "Schildansturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nStürmt in Richtung eines entfernten Ziels. Fügt allen Gegnern auf dem Weg zum Ziel körperlichen Schaden zu und stößt sie zurück. Der Schaden richtet sich nach der zurückgelegten Distanz.\n\nAm Ziel angekommen rammt er seinen Schild in den Boden, fügt Gegnern innerhalb von 10 Metern körperlichen Schaden zu und stößt sie zurück." }
entries[158294] = { ["name"] = "test area trigger", ["text"] = "40 Meter Reichweite\nSofort 3 min Abklingzeit\nBeschwört eine heilige Barriere im Zielbereich, die jeglichen erlittenen Schaden aller verbündeten Ziele innerhalb ihres Bereiches um 20% verringert. Innerhalb der Barriere wird das Wirken von Zaubern durch erlittenen Schaden nicht unterbrochen. Die Barriere hält 10 Sek. lang an." }
entries[158295] = { ["name"] = "test area trigger effect", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört eine heilige Barriere, die alle Verbündeten am Zielort 10 Sek. lang beschützt. Dabei wird sämtlicher durch die Verbündeten erlittene Schaden um 20% verringert und ihr Zauberwirken wird durch Schaden nicht verzögert." }
